<script>
  import { computeGradientDescent, computePreconditioning } from '@/lib/formula-lessons/part4-models.mjs';
  export let lesson; export let spec; let alpha=spec.alpha??.125;
  $: gd=spec.scene==='gd'?computeGradientDescent({Q:spec.Q,x0:spec.x0,alpha:Number(alpha),steps:spec.steps}):null; $: pre=spec.scene==='preconditioning'?computePreconditioning(spec):null; const f=(v,d=4)=>Number(v).toFixed(d); const bar=(v,m)=>Math.max(2,Math.min(100,100*v/Math.max(m,1e-12)));
</script>
<div class="lesson-grid" data-part4-gradient-geometry data-focus={lesson.focus} data-scene={spec.scene}>{#if gd}<section class="panel"><p class="eyebrow">GD trajectory · αL</p><div class="metrics"><div><span>L</span><strong>{f(gd.L,1)}</strong></div><div><span>αL</span><strong>{f(gd.alphaL,3)}</strong></div><div><span>stable?</span><strong>{gd.stable?'YES':'NO'}</strong></div><div><span>monotone?</span><strong>{gd.monotone?'YES':'NO'}</strong></div></div><label>α <output>{f(alpha,3)}</output><input bind:value={alpha} type="range" min=".02" max=".3" step=".005"/></label><div class="bars">{#each gd.history as row (row.k)}<div><span>k={row.k}</span><i style={`width:${bar(row.objective,gd.history[0].objective)}%`}></i><b>{f(row.objective,3)}</b></div>{/each}</div></section><section class="panel"><p class="eyebrow">source-suspect vs corrected bound</p><div class="table-wrap"><table><thead><tr><th>k</th><th>f(xk)</th><th>safe L/(2k)</th><th>normalized αL</th></tr></thead><tbody>{#each gd.history.slice(1) as row,i (row.k)}<tr><td>{row.k}</td><td>{f(row.objective,3)}</td><td>{f(gd.correctedOneOverL[i].bound,3)}</td><td>{f(gd.normalizedGeneral[i].bound,3)}</td></tr>{/each}</tbody></table></div><p class="note">053/059 remain printed source; 218/212 are separate scaling-safe variants.</p></section>{:else if pre}<section class="panel"><p class="eyebrow">preconditioned direction</p><div class="metrics"><div><span>κ before</span><strong>{f(pre.conditionBefore,1)}</strong></div><div><span>κ after</span><strong>{f(pre.conditionAfter,1)}</strong></div><div><span>gᵀd</span><strong>{f(pre.descentInnerProduct,3)}</strong></div><div><span>α exact</span><strong>{f(pre.alphaExact,3)}</strong></div></div><p class="vector">g=[{pre.grad.map(v=>f(v,2)).join(', ')}]<br/>d=[{pre.d.map(v=>f(v,2)).join(', ')}]</p></section><section class="panel"><p class="eyebrow">exact line-search check</p><div class="metrics"><div><span>f before</span><strong>{f(pre.objectiveBefore,3)}</strong></div><div><span>f after</span><strong>{f(pre.objectiveAfter,3)}</strong></div><div><span>∇f(next)ᵀd</span><strong>{f(pre.orthogonalityResidual,8)}</strong></div><div><span>orthogonal?</span><strong>{Math.abs(pre.orthogonalityResidual)<1e-8?'PASS':'FAIL'}</strong></div></div><p class="note">The same P links descent direction, coordinate transform, and exact line-search orthogonality.</p></section>{/if}</div>
<style>.lesson-grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0 0 .5rem;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:.4rem}.metrics div{display:grid;background:var(--color-muted);border-radius:.65rem;padding:.55rem;font-size:.72rem}.metrics span{color:var(--color-muted-foreground)}label{display:grid;grid-template-columns:1fr auto;margin-top:.6rem;font-size:.72rem;font-weight:800}input{grid-column:1/-1;min-height:30px}.bars{display:grid;gap:.26rem;margin-top:.65rem}.bars div{display:grid;grid-template-columns:2.7rem 1fr 4rem;align-items:center;gap:.35rem;font-size:.67rem}.bars i{display:block;height:.5rem;border-radius:999px;background:var(--color-primary)}.bars b{text-align:right}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.68rem}th,td{padding:.4rem;border-bottom:1px solid var(--color-border);text-align:right;white-space:nowrap}.vector{font-family:ui-monospace,monospace;font-size:.74rem}.note{font-size:.73rem;line-height:1.65;color:var(--color-muted-foreground)}@media(max-width:760px){.lesson-grid{grid-template-columns:1fr}}</style>
